#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
bool ok=true;for(int i=0,j=n-1;i<j;++i,--j)if(a[i]!=a[j]){ok=false;break;}
printf("%s\n",ok?"YES":"NO");return 0;}

